"""このファイルはブロックプログラム transformer.blocks.json から自動生成されました。
ここを直接書き換えても、ブロック側には反映されません。
"""
import math
import random


def _devs(api, name, kind=None):
    if name == "*":
        return api.devices(kind)
    return api.devices(name=name)


def _val(api, name, prop, kind=None):
    ds = _devs(api, name, kind)
    if not ds:
        return 0
    d = ds[0]
    if prop == "fuel":
        return d.contents.get("fuel", 0)
    try:
        return getattr(d, prop)
    except Exception:
        return 0


def _div(a, b):
    return a / b if b else 0


def _round(a):
    # 無限大（脱出軌道の遠点など）や非数はそのまま（round では止まってしまうため）
    return round(a) if math.isfinite(a) else a


def _mod(a, b):
    return a % b if b else 0


def _sin(a):
    return math.sin(math.radians(a))


def _cos(a):
    return math.cos(math.radians(a))


def _num(a):
    try:
        return float(a)
    except (TypeError, ValueError):
        return 0.0


def _gravity(api):
    p = api.planet()
    if not p:
        return 0.0
    r2 = sum((api.position[i] - p["center"][i]) ** 2 for i in range(3))
    return p["mu"] / max(r2, 1.0)


def _pos(a):
    return a if a > 0 else 0.0


# --- 矢印（ベクトル）[x, y, z] ---
def _V(a):
    try:
        return [float(a[0]), float(a[1]), float(a[2])]
    except (TypeError, ValueError, IndexError, KeyError):
        return [0.0, 0.0, 0.0]


def _vadd(a, b):
    return [a[0] + b[0], a[1] + b[1], a[2] + b[2]]


def _vsub(a, b):
    return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]


def _vmul(a, k):
    return [a[0] * k, a[1] * k, a[2] * k]


def _vdiv(a, k):
    return [a[0] / k, a[1] / k, a[2] / k] if k else [0.0, 0.0, 0.0]


def _vdot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def _vlen(a):
    return math.sqrt(_vdot(a, a))


def _vunit(a):
    n = _vlen(a)
    return _vmul(a, 1.0 / n) if n > 1e-9 else [0.0, 0.0, 0.0]


def _vclamp(a, n):
    k = _vlen(a)
    return _vmul(a, max(n, 0.0) / k) if k > max(n, 0.0) and k > 0 else list(a)


def _vperp(a, b):
    u = _vunit(b)
    return _vsub(a, _vmul(u, _vdot(a, u)))


def _vangle(a, b):
    na, nb = _vlen(a), _vlen(b)
    if na < 1e-9 or nb < 1e-9:
        return 0.0
    return math.degrees(math.acos(max(-1.0, min(1.0, _vdot(a, b) / (na * nb)))))


def _vtilt(a, b, deg):
    """矢印 a の向きを、b から deg 度以内にする（長さはそのまま）。"""
    n, u = _vlen(a), _vunit(b)
    if n < 1e-9 or _vlen(u) < 0.5:
        return list(a)
    d = _vmul(a, 1.0 / n)
    c, cmax = _vdot(d, u), math.cos(math.radians(max(0.0, min(180.0, deg))))
    if c >= cmax:
        return list(a)
    h = _vunit(_vsub(d, _vmul(u, c)))
    if _vlen(h) < 0.5:
        return _vmul(u, n) if deg < 90 else list(a)
    return _vmul(_vadd(_vmul(u, cmax), _vmul(h, math.sin(math.radians(deg)))), n)


def _vship(api, x, y, z):
    """船から見た (右, 上, 前) → ワールドの矢印。"""
    X, Y, Z = api.orientation()
    return [X[i] * x + Y[i] * y + Z[i] * z for i in range(3)]


def _vcomp(api, a, axis):
    if axis in "xyz":
        return a["xyz".index(axis)]
    X, Y, Z = api.orientation()
    return _vdot(a, {"r": X, "u": Y, "f": Z}[axis])


def _vget(v, name):
    x = v.get(name)
    return list(x) if isinstance(x, list) and len(x) == 3 else [0.0, 0.0, 0.0]


def _to_planet(api):
    p = api.planet()
    return _vsub(p["center"], api.position) if p else [0.0, 0.0, 0.0]


def _txt(a):
    if isinstance(a, list):
        return "(" + ", ".join("%.1f" % x for x in a) + ")"
    return str(a)


def _radio(api, ch):
    v = api.latest(str(ch))
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0



def tick(api):
    m = api.memory
    if api.time - m.get('_last', -99.0) > 0.5:   # 起動し直したら最初から
        m.clear()
    m['_last'] = api.time
    v = m.setdefault('vars', {})
    first = '_t0' not in m
    if first:
        m['_t0'] = api.time
        m['_timer'] = api.time
    keys = api.input
    prev = set(m.get('_keys', []))
    m['_keys'] = sorted(keys)
    # --- 起動したとき ---
    if first:
        v['変形'] = 0
        v['地面'] = api.altitude
        v['浮く高さ'] = 0
        v['前傾き目標'] = 0
        v['右傾き目標'] = 0
        v['前後の補正'] = 0
        v['左右の補正'] = 0
    # --- キー q を押したとき ---
    if 'q' in keys and 'q' not in prev:
        if bool(api.seated):
            v['変形'] = (1 - v.get('変形', 0))
            v['前傾き目標'] = 0
            v['右傾き目標'] = 0
    # --- ずっと（0.05秒ごと） ---
    if (not bool(api.seated)):
        v['変形'] = 0
    if bool(api.seated):
        v['前'] = (('w' in keys) - ('s' in keys))
        v['右'] = (('d' in keys) - ('a' in keys))
        v['上'] = (('space' in keys) - ('left shift' in keys))
        v['旋回目標'] = ((('right arrow' in keys) - ('left arrow' in keys)) * 40)
    else:
        v['前'] = 0
        v['右'] = 0
        v['上'] = 0
        v['旋回目標'] = 0
    if bool(api.seated):
        for d in _devs(api, 'ハッチ', 'actuator'):
            d.rotate_to(0, speed=90)
    else:
        for d in _devs(api, 'ハッチ', 'actuator'):
            d.rotate_to(90, speed=90)
    if (v.get('変形', 0) == 1):
        for d in _devs(api, '左肩', 'actuator'):
            d.rotate_to(180, speed=120)
        for d in _devs(api, '右肩', 'actuator'):
            d.rotate_to(-180, speed=120)
        for d in _devs(api, '左腰', 'actuator'):
            d.rotate_to(90, speed=120)
        for d in _devs(api, '右腰', 'actuator'):
            d.rotate_to(90, speed=120)
        for d in _devs(api, '背中', 'actuator'):
            d.rotate_to(90, speed=120)
    else:
        for d in _devs(api, '左肩', 'actuator'):
            d.rotate_to(0, speed=120)
        for d in _devs(api, '右肩', 'actuator'):
            d.rotate_to(0, speed=120)
        for d in _devs(api, '左腰', 'actuator'):
            d.rotate_to(0, speed=120)
        for d in _devs(api, '右腰', 'actuator'):
            d.rotate_to(0, speed=120)
        for d in _devs(api, '背中', 'actuator'):
            d.rotate_to(0, speed=120)
    v['変形中'] = 0
    if (bool(_val(api, '左肩', 'busy')) or (bool(_val(api, '背中', 'busy')) or bool(_val(api, '左腰', 'busy')))):
        v['変形中'] = 1
    if (bool(api.seated) and (v.get('浮く高さ', 0) < 0.6)):
        v['浮く高さ'] = 1.2
    if ((v.get('変形', 0) == 1) and (v.get('変形中', 0) == 0)):
        v['浮く高さ'] = (api.altitude - v.get('地面', 0))
        v['差'] = ((v.get('前', 0) * 40) - v.get('前傾き目標', 0))
        if (v.get('差', 0) > 0.75):
            v['差'] = 0.75
        if (v.get('差', 0) < -0.75):
            v['差'] = -0.75
        v['前傾き目標'] = _num(v.get('前傾き目標', 0)) + v.get('差', 0)
        v['差'] = ((v.get('右', 0) * 40) - v.get('右傾き目標', 0))
        if (v.get('差', 0) > 0.75):
            v['差'] = 0.75
        if (v.get('差', 0) < -0.75):
            v['差'] = -0.75
        v['右傾き目標'] = _num(v.get('右傾き目標', 0)) + v.get('差', 0)
        v['前後の補正'] = _num(v.get('前後の補正', 0)) + ((v.get('前傾き目標', 0) - math.degrees(math.atan2(-api.up_local[2], api.up_local[1]))) * 0.0006)
        v['左右の補正'] = _num(v.get('左右の補正', 0)) + ((v.get('右傾き目標', 0) - math.degrees(math.atan2(-api.up_local[0], api.up_local[1]))) * 0.0006)
        if (v.get('前後の補正', 0) > 0.25):
            v['前後の補正'] = 0.25
        if (v.get('前後の補正', 0) < -0.25):
            v['前後の補正'] = -0.25
        if (v.get('左右の補正', 0) > 0.25):
            v['左右の補正'] = 0.25
        if (v.get('左右の補正', 0) < -0.25):
            v['左右の補正'] = -0.25
        v['前後'] = ((((v.get('前傾き目標', 0) - math.degrees(math.atan2(-api.up_local[2], api.up_local[1]))) * 0.03) - (math.degrees(api.angular_velocity_local[0]) * 0.02)) + v.get('前後の補正', 0))
        v['左右'] = ((((v.get('右傾き目標', 0) - math.degrees(math.atan2(-api.up_local[0], api.up_local[1]))) * 0.03) - (-math.degrees(api.angular_velocity_local[2]) * 0.02)) + v.get('左右の補正', 0))
        v['加速'] = ((v.get('上', 0) * 3) - (api.vertical_speed * 1.5))
        if (v.get('加速', 0) > 4):
            v['加速'] = 4
        if (v.get('加速', 0) < -4):
            v['加速'] = -4
        v['出力'] = _div((api.mass * (_gravity(api) + v.get('加速', 0))), (1200000 * _cos(math.degrees(math.acos(max(-1.0, min(1.0, api.up_local[1])))))))
        if (v.get('上', 0) > 0.5):
            v['出力'] = 0.8
        if (v.get('出力', 0) > 0.8):
            v['出力'] = 0.8
        if (v.get('出力', 0) < 0):
            v['出力'] = 0
        for d in _devs(api, 'バルブ 後左', 'valve'):
            d.open = max(0.0, min(1.0, (((v.get('出力', 0) + v.get('前後', 0)) + v.get('左右', 0)) + 0.02)))
        for d in _devs(api, 'バルブ 後右', 'valve'):
            d.open = max(0.0, min(1.0, (((v.get('出力', 0) + v.get('前後', 0)) - v.get('左右', 0)) + 0.02)))
        for d in _devs(api, 'バルブ 前左', 'valve'):
